// Subset of vsia.guardrails.redact() (emails, phone numbers, VINs, card numbers, plates).
// The Python service remains the system of record (ADR-0001); this keeps PII out of the LLM call here.
// NHTSA-coded labels (components_raw, component_primary) are dropped: they are evaluation ground truth.
const EMAIL = /(?<![\w.+-])[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
const VIN = /\b(?=(?:[A-HJ-NPR-Z]*\d){2})[A-HJ-NPR-Z0-9]{8}[0-9X][A-HJ-NPR-Z0-9]{8}\b/g;
const CARD = /(?<![\w.])\d(?:[ -]?\d){12,18}(?!\w|\.\d)/g;
const PHONE = /(?<![\w.-])(?:\+?1[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}(?![\w])/g;
const PLATE = /(\b(?:licen[cs]e|tag)\s+plate(?:\s+(?:number|no\.?|#))?\s*[:#]?\s*)[A-Z0-9]{2,4}[ -]?[A-Z0-9]{1,5}\b/gi;
const redact = (t) => String(t || '')
  .replace(EMAIL, '[EMAIL]').replace(VIN, '[VIN]').replace(CARD, '[CARD]')
  .replace(PHONE, '[PHONE]').replace(PLATE, '$1[PLATE]');

const b = $json.body || {};
if (!b.odi_number || !b.summary) {
  throw new Error('send {odi_number, make, model, model_year, summary}');
}
const complaint = {
  odi_number: Number(b.odi_number), make: b.make || null, model: b.model || null,
  model_year: b.model_year ? Number(b.model_year) : null, summary: redact(b.summary),
};
const prompt = `Vehicle: ${complaint.make} ${complaint.model} ${complaint.model_year}\n` +
  `<complaint>\n${complaint.summary}\n</complaint>`;
return [{ json: { complaint, prompt } }];

