// Native-variant routing uses the model's own confidence only (no calibration signals), so its records are
// tagged run_id n8n-native-<execution> and prompt_version n8n-native-v1 for separate evaluation.
const out = $json.output;
const complaint = $('Redact PII').first().json.complaint;
const threshold = Number($env.VSIA_CONFIDENCE_THRESHOLD || 0.7);
const route = out.model_confidence >= threshold && !out.injection_suspected ? 'auto' : 'review';
return [{ json: {
  odi_number: complaint.odi_number,
  run_id: `n8n-native-${$execution.id}`,
  schema_version: '1.0',
  component: out.component,
  severity: out.severity,
  recall_campaigns: JSON.stringify((out.recall_matches || []).map(m => m.campaign_number)),
  confidence: out.model_confidence,
  confidence_signals: JSON.stringify({ model_confidence: out.model_confidence }),
  route,
  output: JSON.stringify(out),
  cited_sources: JSON.stringify((out.recall_matches || []).map(m => `recall:${m.campaign_number}`)),
  provider: 'anthropic',
  model: 'claude-haiku-5-5',
  prompt_version: 'n8n-native-v1',
  triage: out,
} }];
